// This file is generated by AI.

// 试听按钮 (全局互斥播放)。
//
// 共享组件: 参考音频列表、配音记录列表都用它。播放中按钮进入 active 态,
// 这样"现在响的是哪一条"一目了然 —— 尤其列表中往往有几十条音频。

import { Button } from '@fluentui/react-components';
import { PlayRegular, StopRegular } from '@fluentui/react-icons';
import { useEffect, useRef, useState } from 'react';

import { voiceReadAudio } from '../commands/voice';

interface Props {
  path: string;
  /** 悬浮提示里的补充说明 (通常是参考文本) */
  label?: string;
}

export function AudioButton({ path, label }: Props) {
  const [playing, setPlaying] = useState(false);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  useEffect(() => {
    return () => {
      audioRef.current?.pause();
      audioRef.current = null;
    };
  }, []);

  const toggle = async () => {
    if (playing) {
      audioRef.current?.pause();
      setPlaying(false);
      return;
    }
    try {
      const dataUrl = await voiceReadAudio(path);
      // 全局互斥: 停止其他正在播放的音频
      document.querySelectorAll<HTMLAudioElement>('audio[data-voice-preview]').forEach((element) => element.pause());
      const audio = new Audio(dataUrl);
      audio.dataset['voicePreview'] = 'true';
      audio.onended = () => setPlaying(false);
      audio.onerror = () => setPlaying(false);
      audioRef.current = audio;
      await audio.play();
      setPlaying(true);
    } catch {
      setPlaying(false);
    }
  };

  return (
    <Button
      size="small"
      appearance="subtle"
      className={playing ? 'audio-button playing' : 'audio-button'}
      icon={playing ? <StopRegular /> : <PlayRegular />}
      title={playing ? '停止试听' : `试听${label ? `：${label}` : ''}`}
      onClick={() => void toggle()}
    />
  );
}
